P = "/home/user/gp-rarelink/data/literature/ha20/fulltext_md/41675327.md"
lines = open(P, encoding="utf-8").read().split("\n")

hdr = lines[350]
hdr_extra = lines[349]
labels = ["Case", "Age at VCE", "Gender", "Genotype", "Classification",
          "Duodenum on VCE", "Jejunum on VCE", "Ileum on VCE",
          "Colonic feature on colonoscopy", "Ileal feature on colonoscopy",
          "Gastric feature on gastroscopy", "Histology", "Treatment"]
cols = [(hdr.find(l), l) for l in labels]
for l in ["Duodenal bulb feature on", "Descending part of the"]:
    cols.append((hdr_extra.find(l), l))
cols.sort()
print("column start offsets:")
for i, l in cols:
    print(i, repr(l))
print()

bounds = [c[0] for c in cols] + [10 ** 6]

def cells(line):
    out = []
    for k in range(len(cols)):
        out.append(line[bounds[k]:bounds[k + 1]].strip())
    return out

rows = {}
for idx in range(353, 470):
    ln = lines[idx]
    if re.match(r"^\s*Patient \d+", ln):
        rows[idx + 1] = (ln, cells(ln))

for n, (ln, c) in rows.items():
    if c[3] == "TNFAIP3" or re.match(r"^Patient (2|5|9|12)\b", ln.strip()):
        print(n, json.dumps(c, ensure_ascii=False))
